//! Compares `load`/`load_text` with upstream's real readers on the corpus in
//! `tests/fixtures/loader/corpus.json` (generated by `scripts/loader/gen_fixtures.py`).

use openapi_spec_validator_rs::loader::{TextErrors, load, load_text};
use serde_json::{Value, json};

/// The type-explicit encoding `scripts/upstream.py` writes: floats as IEEE bits, ints as digits.
fn tagged(v: &Value) -> Value {
    match v {
        Value::Null => json!(["n"]),
        Value::Bool(b) => json!(["b", b]),
        Value::Number(n) => match (n.as_i64(), n.as_u64(), n.as_f64()) {
            (Some(i), _, _) => json!(["i", i.to_string()]),
            (_, Some(u), _) => json!(["i", u.to_string()]),
            (_, _, Some(f)) => json!(["f", format!("{:016x}", f.to_bits())]),
            _ => json!(["?"]),
        },
        Value::String(s) => json!(["s", s]),
        Value::Array(items) => json!(["l", items.iter().map(tagged).collect::<Vec<_>>()]),
        Value::Object(map) => json!([
            "d",
            map.iter()
                .map(|(k, v)| json!([k, tagged(v)]))
                .collect::<Vec<_>>()
        ]),
    }
}

/// Python ints beyond 64 bits are expected as the f64 serde_json parses from their digits.
fn normalize_expected(v: &Value) -> Value {
    let Some(items) = v.as_array() else {
        return v.clone();
    };
    match (items.first().and_then(Value::as_str), items.get(1)) {
        (Some("i"), Some(Value::String(digits))) => {
            if digits.parse::<i64>().is_ok() || digits.parse::<u64>().is_ok() {
                v.clone()
            } else {
                match serde_json::from_str::<Value>(digits) {
                    Ok(parsed) => tagged(&parsed),
                    Err(_) => json!(["n"]),
                }
            }
        }
        (Some("l"), Some(Value::Array(children))) => {
            json!([
                "l",
                children.iter().map(normalize_expected).collect::<Vec<_>>()
            ])
        }
        (Some("d"), Some(Value::Array(entries))) => json!([
            "d",
            entries
                .iter()
                .map(|e| json!([e[0].clone(), normalize_expected(&e[1])]))
                .collect::<Vec<_>>()
        ]),
        _ => v.clone(),
    }
}

fn nesting_depth(v: &Value) -> usize {
    let mut depth = 0;
    let mut cur = v;
    loop {
        let next = match cur {
            Value::Array(items) => items.first(),
            Value::Object(map) => map.values().next(),
            _ => return depth,
        };
        depth += 1;
        match next {
            Some(n) => cur = n,
            None => return depth,
        }
    }
}

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn run_corpus() -> (usize, Vec<String>) {
    let corpus: Vec<Value> =
        serde_json::from_str(include_str!("fixtures/loader/corpus.json")).expect("corpus parses");
    let mut failures = Vec::new();
    for fixture in &corpus {
        let name = fixture["name"].as_str().unwrap();
        let mode = fixture["mode"].as_str().unwrap();
        let input = hex(fixture["input"].as_str().unwrap());
        let result = match mode {
            "file" => load(&input, "<urllib response>"),
            "text-strict" => load_text(&input, "<stdin>", TextErrors::Strict),
            _ => load_text(&input, "<stdin>", TextErrors::SurrogateEscape),
        };
        let verdict = match (
            &result,
            fixture.get("err"),
            fixture.get("ok"),
            fixture.get("ok_depth"),
        ) {
            (Err(e), Some(want), _, _) if want.as_str() == Some(e.message.as_str()) => Ok(()),
            (Ok(v), _, Some(want), _) if tagged(v) == normalize_expected(want) => Ok(()),
            (Ok(v), _, _, Some(d)) if d.as_u64() == Some(nesting_depth(v) as u64) => Ok(()),
            (got, _, _, _) => Err(format!(
                "{name} [{mode}]\n  got:  {}\n  want: {}",
                match got {
                    Ok(v) => truncate(tagged(v).to_string()),
                    Err(e) => format!("Err({:?})", e.message),
                },
                truncate(
                    fixture
                        .get("err")
                        .map(|e| format!("Err({e})"))
                        .or_else(|| fixture.get("ok").map(|v| normalize_expected(v).to_string()))
                        .or_else(|| fixture.get("ok_depth").map(|d| format!("depth {d}")))
                        .unwrap_or_default()
                )
            )),
        };
        if let Err(message) = verdict {
            failures.push(message);
        }
        // Deep values are dropped here, on the big-stack thread.
        drop(result);
    }
    (corpus.len(), failures)
}

fn truncate(s: String) -> String {
    if s.len() > 400 {
        format!(
            "{}…",
            &s[..s.char_indices().nth(400).map_or(s.len(), |(i, _)| i)]
        )
    } else {
        s
    }
}

#[test]
fn corpus_matches_upstream() {
    // Values nested ~10 000 deep need more than the default test-thread stack to drop.
    let (total, failures) = std::thread::Builder::new()
        .stack_size(256 << 20)
        .spawn(run_corpus)
        .unwrap()
        .join()
        .unwrap();
    assert!(total >= 150, "corpus too small: {total}");
    assert!(
        failures.is_empty(),
        "{} of {total} fixtures differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
